import cors from 'cors';
import { PGLite } from '@electric-sql/pglite';

const app = express();
const PORT = process.env.PORT || 3001;

// Middleware
app.use(cors());
app.use(express.json());
app.use(express.static('public'));

// Initialize PGLite database
const dbDir = './data';
const pg = new PGLite({ location: dbDir });

// Initialize database
async function initDatabase() {
  try {
    // Create messages table if it doesn't exist
    await pg.query(`
      CREATE TABLE IF NOT EXISTS messages (
        id SERIAL PRIMARY KEY,
        text TEXT NOT NULL,
        created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
      )
    `);

    console.log('Database initialized successfully');
  } catch (error) {
    console.error('Error initializing database:', error);
    process.exit(1);
  }
}

// Historical messages endpoint
app.get('/api/messages', async (req, res) => {
  try {
    const result = await pg.query('SELECT * FROM messages ORDER BY created_at ASC');
    res.json(result.rows);
  } catch (error) {
    console.error('Error fetching messages:', error);
    res.status(500).json({ error: 'Failed to fetch messages' });
  }
});

// SSE endpoint for real-time updates
const clients = new Set();
let messageId = 0;

app.get('/api/stream', (req, res) => {
  res.setHeader('Content-Type', 'text/event-stream');
  res.setHeader('Cache-Control', 'no-cache');
  res.setHeader('Connection', 'keep-alive');
  res.setHeader('Access-Control-Allow-Origin', '*');

  const clientId = Date.now();
  const client = {
    id: clientId,
    res
  };
  clients.add(client);

  console.log(`Client connected. Total clients: ${clients.size}`);

  // Send a ping every 30 seconds to keep alive
  const heartbeat = setInterval(() => {
    const ping = `event: ping\ndata: ${new Date().toISOString()}\n\n`;
    client.res.write(ping);
  }, 30000);

  // Clean up on disconnect
  req.on('close', () => {
    clearInterval(heartbeat);
    clients.delete(client);
    console.log(`Client disconnected. Total clients: ${clients.size}`);
  });
});

// Broadcast a new message to all connected clients
function broadcastMessage(message) {
  const eventData = JSON.stringify(message);
  const data = `data: ${eventData}\n\n`;
  const errorData = `data: ${JSON.stringify({ error: 'Failed to send message' })}\n\n`;

  clients.forEach(client => {
    try {
      client.res.write(data);
    } catch (error) {
      console.error('Error broadcasting to client:', error);
    }
  });
}

// Messaging endpoint
app.post('/api/messages', async (req, res) => {
  try {
    const { text } = req.body;

    if (!text || typeof text !== 'string') {
      return res.status(400).json({ error: 'Text is required' });
    }

    // Insert into database
    const result = await pg.query(
      'INSERT INTO messages (text) VALUES ($1) RETURNING id, text, created_at',
      [text]
    );

    const newMessage = result.rows[0];

    // Broadcast to all connected clients
    broadcastMessage(newMessage);

    res.status(201).json(newMessage);
  } catch (error) {
    console.error('Error creating message:', error);
    res.status(500).json({ error: 'Failed to create message' });
  }
});

// Start server
app.listen(PORT, async () => {
  await initDatabase();
  console.log(`Server running on port ${PORT}`);
  console.log(`SSE endpoint: http://localhost:${PORT}/api/stream`);
  console.log(`API endpoint: http://localhost:${PORT}/api/messages`);
});
"}

{"path": "/tmp/runs/smokes/glm-q4/message-board/interactive/runs/301/app/public/main.js", "content": "// DOM elements
const messageList = document.getElementById('message-list');
const messageForm = document.getElementById('message-form');
const messageInput = document.getElementById('message-input');

// Base URL for API
const API_BASE = 'http://localhost:3001';

// State
let messages = [];
let eventSource = null;

// Render a single message
function renderMessage(message) {
  const messageElement = document.createElement('div');
  messageElement.className = 'message';
  messageElement.dataset.id = message.id;

  const time = new Date(message.created_at).toLocaleTimeString();

  messageElement.innerHTML = `
    <div class="message-content">${escapeHtml(message.text)}</div>
    <div class="message-time">${time}</div>
  `;

  // Insert at the top of the list
  messageList.insertBefore(messageElement, messageList.firstChild);
}

// Render all messages
function renderMessages() {
  messageList.innerHTML = '';
  messages.forEach(message => renderMessage(message));
}

// Escape HTML to prevent XSS
function escapeHtml(text) {
  const div = document.createElement('div');
  div.textContent = text;
  return div.innerHTML;
}

// Fetch initial messages
async function fetchMessages() {
  try {
    const response = await fetch(`${API_BASE}/api/messages`);
    if (!response.ok) {
      throw new Error('Failed to fetch messages');
    }
    messages = await response.json();
    renderMessages();
  } catch (error) {
    console.error('Error fetching messages:', error);
    messageList.innerHTML = '<p class="error">Failed to load messages. Please refresh the page.</p>';
  }
}

// Connect to SSE stream
function connectToStream() {
  eventSource = new EventSource(`${API_BASE}/api/stream`);

  eventSource.onmessage = (event) => {
    try {
      const data = JSON.parse(event.data);

      if (data.event === 'ping') {
        // Heartbeat - ignore
        return;
      }

      if ('id' in data && 'text' in data && 'created_at' in data) {
        // New message received
        messages.push(data);
        renderMessage(data);
      }
    } catch (error) {
      console.error('Error processing SSE message:', error);
    }
  };

  eventSource.onerror = (error) => {
    console.error('SSE error:', error);
    eventSource.close();
    // Reconnect after 5 seconds
    setTimeout(connectToStream, 5000);
  };

  console.log('Connected to SSE stream');
}

// Send a new message
async function sendMessage(text) {
  try {
    const response = await fetch(`${API_BASE}/api/messages`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({ text }),
    });

    if (!response.ok) {
      const error = await response.json();
      throw new Error(error.error || 'Failed to send message');
    }

    const newMessage = await response.json();
    messages.push(newMessage);
    renderMessage(newMessage);
    messageInput.value = '';
  } catch (error) {
    console.error('Error sending message:', error);
    alert('Failed to send message. Please try again.');
  }
}

// Handle form submission
messageForm.addEventListener('submit', (event) => {
  event.preventDefault();
  const text = messageInput.value.trim();
  if (text) {
    sendMessage(text);
  }
});

// Initialize the app
console.log('Initializing message board...');
fetchMessages();
connectToStream();
"}

